// Finds Pinterest pins that failed since the last check and builds ONE plain-language digest.
// A failure is reported once: its key is only written to the Alert Log (by "Append Alert Log") AFTER the email went out.
const cfg = $('Config (Failures)').first().json;
// Already-reported failures live in the 'Alert Log' tab (column Key). Rows older than 30 days are ignored.
const alerted = {};
const lastSent = {};   // cause -> when it was last emailed
for (const it of $('Read Alert Log').all()) {
  const r = it.json || {};
  const k = String(r['Key'] == null ? '' : r['Key']).trim();
  if (!k) continue;
  const at = DateTime.fromISO(String(r['Reported At'] || ''));
  if (at.isValid && $now.diff(at, 'days').days > 30) continue;
  alerted[k] = true;
  const d = String(r['Details'] || '');
  const cause = d.includes(' | ') ? d.split(' | ').slice(1).join(' | ') : d;
  if (at.isValid && cause && (!lastSent[cause] || at > lastSent[cause])) lastSent[cause] = at;
}
const cooldownHours = cfg.cooldownHours == null ? 12 : Number(cfg.cooldownHours);

const str = v => (v == null ? '' : String(v).trim());
function friendly(raw) {
  const r = str(raw);
  if (/disconnect/i.test(r)) return 'Pinterest is disconnected in Metricool. Please reconnect it: Metricool > Connections > Pinterest.';
  if (/account limit|monthly|quota/i.test(r)) return "Metricool's monthly post limit was reached.";
  if (/not found/i.test(r) && /pin/i.test(r)) return 'Pinterest could not find the pin.';
  if (/token|authoriz/i.test(r)) return 'Pinterest login expired. Please reconnect it in Metricool.';
  return r ? r.slice(0, 140) : 'Unknown error';
}

const fails = [];
let metricoolCheckFailed = false;
for (const it of $('Get Recent Metricool Posts').all()) {
  const j = it.json || {};
  if (j.error) { metricoolCheckFailed = true; continue; }
  const list = Array.isArray(j.data) ? j.data : Array.isArray(j.posts) ? j.posts : Array.isArray(j) ? j : (j.id ? [j] : []);
  for (const p of list) {
    const prov = (p.providers || []).find(x => String(x.network).toLowerCase() === 'pinterest');
    if (!prov || String(prov.status).toUpperCase() !== 'ERROR') continue;
    const key = 'mc:' + p.id;
    if (alerted[key]) continue;
    fails.push({ key, when: str((p.publicationDate || {}).dateTime).slice(0, 16).replace('T', ' '), reason: friendly(prov.detailedStatus), kind: 'metricool' });
  }
}
if (metricoolCheckFailed) {
  const key = 'chk:' + $now.toFormat('yyyy-LL-dd');
  if (!alerted[key]) fails.push({ key, when: '', reason: 'The pin check could not reach Metricool just now. If this repeats, please let Bilal know.', kind: 'check' });
}
for (const [tab, name] of [[cfg.pinsTab, 'Blog pins'], [cfg.pinsTab2, '2:3 pins']]) {
  const rows = $(tab === cfg.pinsTab ? 'Get Pins (Failures)' : 'Get Pins 2 (Failures)').all();
  for (const it of rows) {
    const p = it.json || {};
    if (str(p['Status']).toLowerCase() !== 'error') continue;
    const key = 'row:' + name + ':' + str(p['Pin ID']) + ':' + str(p['Error']).slice(0, 60);
    if (alerted[key]) continue;
    fails.push({ key, when: str(p['Scheduled Date']), reason: friendly(p['Error']), kind: name });
  }
}
// Same cause already emailed within the cooldown (default 12 h): hold these back. They are NOT logged,
// so the first run after the cooldown reports everything that failed since in one email. This keeps a
// standing problem (e.g. Pinterest disconnected, one pin failing every hour) from sending an email an hour.
const reportable = fails.filter(f => {
  const last = lastSent[f.reason];
  return !(last && $now.diff(last, 'hours').hours < cooldownHours);
});
if (reportable.length === 0) return [];
fails.length = 0; fails.push(...reportable);

const groups = {};
for (const f of fails) (groups[f.reason] = groups[f.reason] || []).push(f);
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
let html = '<div style="font-family:Arial,sans-serif;line-height:1.5;color:#333">';
html += '<p>Hi Raenia,</p><p><strong>' + fails.length + ' Pinterest pin' + (fails.length === 1 ? '' : 's') + ' failed to publish.</strong></p>';
for (const [reason, list] of Object.entries(groups)) {
  const dates = list.filter(f => f.when).map(f => f.when).sort().slice(0, 6);
  html += '<p><strong>' + list.length + ' pin' + (list.length === 1 ? '' : 's') + ':</strong> ' + esc(reason) + (dates.length ? '<br><span style="color:#777">Scheduled for: ' + dates.join(', ') + (list.length > dates.length ? ' ...' : '') + '</span>' : '') + '</p>';
}
html += '<p>Pins that failed are not published automatically. Once the cause is fixed, the failed pins will be resent.</p></div>';
const subject = 'Pinterest: ' + fails.length + ' pin' + (fails.length === 1 ? '' : 's') + ' failed to publish';
return [{ json: { to: cfg.alertTo, cc: cfg.alertCc, subject, body: html, entries: fails.map(f => ({ key: f.key, details: (f.when ? f.when + ' | ' : '') + f.reason })) } }];

// One row per reported failure, written to the 'Alert Log' tab AFTER the email was sent.
const entries = $('Find New Failures').first().json.entries || [];
const at = $now.toISO();
return entries.map(e => ({ json: { 'Key': e.key, 'Reported At': at, 'Details': String(e.details || '').slice(0, 200) } }));

// Daily check, blog pins and 2:3 pins SEPARATELY. Stock = pins scheduled in the future
// + approved pins waiting to be scheduled. Days left = stock / pins per day.
const cfg = $('Config (Stock)').first().json;
const str = v => (v == null ? '' : String(v).trim());
const norm = v => str(v).toLowerCase();
function parseDate(s) {
  const v = str(s); if (!v) return null;
  for (const f of ['yyyy-LL-dd HH:mm', 'yyyy-LL-dd H:mm', 'M/d/yyyy HH:mm:ss', 'M/d/yyyy H:mm:ss', 'M/d/yyyy H:mm']) {
    const dt = DateTime.fromFormat(v, f); if (dt.isValid) return dt;
  }
  const d = new Date(v); return isNaN(d.getTime()) ? null : DateTime.fromJSDate(d);
}
function count(items) {
  let scheduled = 0, ready = 0, needsBoard = 0;
  for (const it of items) {
    const p = it.json || {};
    const st = norm(p['Status']), ap = norm(p['Approval']);
    if (st === 'scheduled') { const dt = parseDate(p['Scheduled Date']); if (dt && dt > $now) scheduled++; }
    else if (st === 'review' && ap === 'approved') ready++;
    else if (st === 'needs board') needsBoard++;
  }
  return { scheduled, ready, needsBoard };
}
const tabs = [
  { name: 'Blog pins', perDay: Number(cfg.blogPerDay) || 15, items: $('Get Pins (Stock)').all() },
  { name: '2:3 pins', perDay: Number(cfg.photoPerDay) || 5, items: $('Get Pins 2 (Stock)').all() }
];
const lowDays = Number(cfg.lowDays) || 2;
const lines = [];
for (const t of tabs) {
  const c = count(t.items);
  const stock = c.scheduled + c.ready;
  const days = stock / t.perDay;
  if (days <= lowDays) {
    const left = days < 1 ? 'less than 1 day' : 'about ' + Math.floor(days) + ' day' + (Math.floor(days) === 1 ? '' : 's');
    lines.push('<p><strong>' + t.name + ' are running low:</strong> ' + (stock === 0 ? 'none left to publish' : left + ' of pins left (' + stock + ' pins at ' + t.perDay + ' a day)') + '.' +
      (c.needsBoard ? '<br><span style="color:#777">' + c.needsBoard + ' more are waiting for a board ID and are not counted.</span>' : '') + '</p>');
  }
}
if (lines.length === 0) return [];
const html = '<div style="font-family:Arial,sans-serif;line-height:1.5;color:#333"><p>Hi Raenia,</p>' + lines.join('') + '<p>Please add new content so posting is not interrupted.</p></div>';
return [{ json: { to: cfg.alertTo, cc: cfg.alertCc, subject: 'Pinterest: pins running low', body: html } }];
